{
  "description": "The creature is a single quadrupedal animal shown in right-facing three-quarter view walking on a pale ground. It has a broad, flat, pale pinkish-tan head with large dark eyes and a wide mouth, six feathery external gills around the neck, a stout arched body whose dorsal surface from the neck to the tail is densely covered in overlapping dark brown rounded scales with lighter edges, pale wrinkled skin on the ventral side, throat, limbs and tail underside, four short thick limbs positioned under the body, and a thick tapering tail extending to the left and partially out of frame.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat and rounded axolotl-like head, pale pinkish-beige with slightly darker mottling on the crown, large round dark eyes with pale blue-grey irises on the sides, two small nostrils on the snout tip, and a closed mouth with a slight upturn",
      "where": "at the front right of the body, facing slightly toward the viewer"
    },
    {
      "part": "gills",
      "looks_like": "six feathery external gills, pinkish-red stalks with dense filamentous frills along the edges, three on each side of the head",
      "where": "projecting outward from just behind the jaw on both left and right sides of the neck"
    },
    {
      "part": "scales",
      "looks_like": "overlapping keratinous scales, dark brown to grey-brown with lighter tan rims and fine radial striations, rounded and plate-like, arranged in rows",
      "where": "covering the entire dorsal back, sides and top of the tail from immediately behind the gills to the rear"
    },
    {
      "part": "legs",
      "looks_like": "four short, stout, fleshy limbs with wrinkled pale pinkish-tan skin and visible skin folds at the joints",
      "where": "two forelegs under the chest and two hindlegs under the mid-body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad five-toed feet with short dark claws on each toe, fleshy and slightly splayed",
      "where": "at the distal end of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick, tapering, muscular tail, scaled on the dorsal surface like the back and pale wrinkled skin ventrally",
      "where": "extending to the left from the rear of the body, partially cropped at the image edge"
    },
    {
      "part": "markings",
      "looks_like": "subtle darker mottling on the head and faint transverse wrinkles/folds on the throat, belly and limb joints, no distinct spots or stripes",
      "where": "on the pale skin of the head, throat, ventral torso and limbs"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
